W=$HOME/work/loop; for r in $W/runs/s[pg]*/; do n=$(basename $r); [ -e $r/results.jsonl ] && echo "$n:$(wc -l < $r/results.jsonl):$(ls $r/episodes 2>/dev/null | wc -l)"; done | tr "\n" " "; echo; ls $W/pub/rows 2>/dev/null | grep -v log | sed "s/-[0-9]*\.npz//" | sort | uniq -c | tr "\n" " "; echo; ls $W/arena 2>/dev/null | head; ls -d $W/r4* $W/arena* 2>/dev/null; grep -c . $W/arena*/new.txt 2>/dev/null; tail -n 4 $W/arena*/arena.log 2>/dev/null | cut -c1-200; grep MATCH $W/human.log | tail -n 2 | cut -c1-170; date -u +%T
